def Smallestonleft(arr, n):
	ans = []
	s = []
	from bisect import bisect_left

	def BinarySearch(a, x):
		i = bisect_left(a, x)
		if i:
			return i - 1
		else:
			return -1
	res = [-1] * (n + 1)
	lst = []
	lst.append(arr[0])
	for i in range(1, n):
		idx = BinarySearch(lst, arr[i])
		if idx != -1:
			res[i] = lst[idx]
		lst.insert(idx + 1, arr[i])
	for i in range(n):
		print(res[i], end=' ')
	return []
